import clsx from "clsx";

import "./entry-tree.css";

/**
 * @summary route-local 엔트리 트리 속성
 */
interface EntryTreeProps {
  /**
   * @field 표시할 엔트리 목록
   */
  entries: Array<{id: string; label: string}>;
  /**
   * @field 선택된 엔트리 ID
   */
  selectedId?: string;
}

export const EntryTree = (props: EntryTreeProps) => {
  const {entries, selectedId} = props;

  return (
    <ul
      className={clsx(
        "rt_entriesEntryTree__list",
        selectedId && "rt_entriesEntryTree__list--selected",
      )}
    >
      {entries.map((entry) => (
        <li key={entry.id}>{entry.label}</li>
      ))}
    </ul>
  );
};
